	@Test
	void mappedV2CostsTypedAndRawMinusWithoutLegacyMaterialization() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbStatisticsService statistics = mock(LmdbStatisticsService.class);
		FrontierStatisticsStatus status = mock(FrontierStatisticsStatus.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		ValueStore valueStore = mock(ValueStore.class);
		when(runtime.statisticsService()).thenReturn(statistics);
		when(runtime.valueStore()).thenReturn(valueStore);
		when(runtime.frontierSettings()).thenReturn(
				LmdbFrontierPlannerSettings.defaults(FrontierEstimatorMode.AUTHORITATIVE, 0L, 0L, 0, 1.0d, 1.0d));
		when(statistics.status()).thenReturn(status);
		when(status.availability()).thenReturn(FrontierStatisticsAvailability.READY);
		when(status.fallbackReason()).thenReturn(FrontierFallbackReason.NONE);
		when(statistics.openCurrentView()).thenReturn(view);
		when(view.ready()).thenReturn(true);
		when(view.estimateLeaf(any())).thenReturn(new FrontierLeafEstimate(
				100.0d, 80.0d, 120.0d, 0.95d, "frontier-v2-omni-leaf", FrontierFallbackReason.NONE));
		var leftPredicate = VF.createIRI("urn:test:mapped-minus:left");
		var rightPredicate = VF.createIRI("urn:test:mapped-minus:right");
		when(valueStore.getId(leftPredicate)).thenReturn(301L);
		when(valueStore.getId(rightPredicate)).thenReturn(302L);
		StatementPattern left = new StatementPattern(
				Var.of("shared"), Var.of("leftPredicate", leftPredicate), Var.of("leftObject"));
		StatementPattern right = new StatementPattern(
				Var.of("shared"), Var.of("rightPredicate", rightPredicate), Var.of("rightObject"));
		var call = PackedCostTestSupport.difference(left, right);

		try (PackedCostSession session = new LmdbPackedCostModel(runtime, OptionalLong.empty(), true)
				.openSession(call.query())) {
			PackedCostEstimate leftEstimate = new PackedCostEstimate();
			PackedCostEstimate rightEstimate = new PackedCostEstimate();
			session.estimateLeaf(call.leftRelationId(), call.emptyContext(), leftEstimate);
			session.estimateLeaf(call.rightRelationId(), call.emptyContext(), rightEstimate);
			var context = call.standaloneContext(
					100_000.0d, 10_000.0d, leftEstimate.evidenceStateId(), rightEstimate.evidenceStateId());

			PackedCostEstimate rawMinus = new PackedCostEstimate();
			rawMinus.setRows(90_000.0d, 110_000.0d);
			session.refineOperator(call.differenceRelationId(), context, rawMinus);
			assertEquals("materialized-hash", rawMinus.plannedStringMetric("optimizer.semiAntiAlgorithm"));
			assertEquals(100_000.0d,
					rawMinus.plannedDoubleMetric("plannedCorrelationOuterRows", Double.NaN), 0.0d);

			int typedAlternatives = 0;
			for (int relationId = 1; relationId <= call.query().relationCount(); relationId++) {
				if (!call.query().isAntiJoin(relationId)) {
					continue;
				}
				typedAlternatives++;
				PackedCostEstimate typedMinus = new PackedCostEstimate();
				typedMinus.setRows(90_000.0d, 110_000.0d);
				session.refineOperator(relationId, context, typedMinus);
				assertNotNull(typedMinus.plannedStringMetric("optimizer.semiAntiAlgorithm"));
				assertEquals(100_000.0d,
						typedMinus.plannedDoubleMetric("plannedCorrelationOuterRows", Double.NaN), 0.0d);
				assertTrue(typedMinus.dependentSubqueriesCosted());
			}
			assertEquals(3, typedAlternatives, "streaming, memoized, and materialized alternatives must all be costed");
			assertFalse(session instanceof LmdbFrontierPackedCostSession,
					"mapped semi/anti costing must not reopen the legacy payload/query-index session");
		}
	}

	@Test
	void mappedV2SemiAntiUsesFrontierSurfaceFeedbackAcrossPrefixLayouts() {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbPackedCostModel costModel = new LmdbPackedCostModel(runtime);
		var query = mock(org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.class);
		StatementPattern left = new StatementPattern(
				Var.of("node"), Var.of("leftPredicate", VF.createIRI("urn:test:left")), Var.of("value"));
		StatementPattern right = new StatementPattern(
				Var.of("node"), Var.of("rightPredicate", VF.createIRI("urn:test:right")), Var.of("blocker"));
		Filter notExists = new Filter(left, new Not(new Exists(right)));
		when(query.relationCount()).thenReturn(3);
		when(query.materializeRelation(1)).thenReturn(notExists);
		when(query.materializeRelation(2)).thenReturn(right);
		when(query.materializeRelation(3)).thenReturn(left);
		when(query.isAntiJoin(1)).thenReturn(true);
		when(query.semiAntiKind(1)).thenReturn(
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_NOT_EXISTS);
		when(query.semiAntiRightRelationId(1)).thenReturn(2);
		when(query.semiAntiCorrelationBindingCount(1)).thenReturn(1);
		when(query.semiAntiCorrelationBindingName(1, 0)).thenReturn("node");
		LmdbOperatorFeedbackStats.SemiAntiEstimate feedback = new LmdbOperatorFeedbackStats.SemiAntiEstimate(
				1L, 100L, 90L, 10L, 100L, 90L, 10L, 0L, 100L, 10L, 100L, 0L, 0L, 0L, 0L, 1L, 100L);
		when(runtime.frontierSemiAntiFeedback(any(Filter.class), eq("NOT_EXISTS"),
				eq("streaming-correlated"))).thenReturn(feedback);
		PackedCostContext context = mock(PackedCostContext.class);
		when(context.leftInputRows()).thenReturn(100.0d);
		when(context.rightInputRows()).thenReturn(100.0d);
		LmdbMappedSemiAntiCosting costing = new LmdbMappedSemiAntiCosting(costModel, query);
		for (int algorithm : new int[] {
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_STREAMING,
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_MEMOIZED,
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_MATERIALIZED }) {
			when(query.semiAntiAlgorithm(1)).thenReturn(algorithm);
			PackedCostEstimate output = new PackedCostEstimate();
			output.setContextualRows(100.0d, 100.0d);

			assertTrue(costing.refine(1, new int[] { 3 }, null, context, output));
			assertEquals(10.0d, output.outputRows(), 0.0d,
					"A logical NOT EXISTS surface must rescale every equivalent physical candidate");
			assertEquals(0.9d, output.plannedDoubleMetric("plannedSemiAntiHitProbability", Double.NaN), 0.0d);
			assertEquals("frontier-semi-anti-surface",
					output.plannedStringMetric("plannedSemiAntiSelectivitySource"));
		}
	}

	@Test
	void mappedV2SemiAntiUsesOmniCorrelationInsteadOfScalarPassThrough() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbStatisticsService statistics = mock(LmdbStatisticsService.class);
		FrontierStatisticsStatus status = mock(FrontierStatisticsStatus.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		ValueStore valueStore = mock(ValueStore.class);
		when(runtime.statisticsService()).thenReturn(statistics);
		when(runtime.valueStore()).thenReturn(valueStore);
		when(runtime.frontierSettings()).thenReturn(
				LmdbFrontierPlannerSettings.defaults(FrontierEstimatorMode.AUTHORITATIVE, 0L, 0L, 0, 1.0d, 1.0d));
		when(statistics.status()).thenReturn(status);
		when(status.availability()).thenReturn(FrontierStatisticsAvailability.READY);
		when(status.fallbackReason()).thenReturn(FrontierFallbackReason.NONE);
		when(statistics.openCurrentView()).thenReturn(view);
		when(view.ready()).thenReturn(true);
		var outerPredicate = VF.createIRI("urn:test:mapped-anti:outer");
		var blockerPredicate = VF.createIRI("urn:test:mapped-anti:blocker");
		when(valueStore.getId(outerPredicate)).thenReturn(501L);
		when(valueStore.getId(blockerPredicate)).thenReturn(502L);
		when(view.estimateLeaf(any())).thenAnswer(invocation -> {
			FrontierLeafProbe probe = invocation.getArgument(0);
			double rows = probe.predicateId() == 502L ? 200.0d : 100.0d;
			return new FrontierLeafEstimate(
					rows, rows, rows, 1.0d, "frontier-v2-omni-leaf", FrontierFallbackReason.NONE);
		});
		when(view.estimateProjectedDistinct(any(), anyInt())).thenReturn(100.0d);
		when(view.estimateJoin(any())).thenReturn(new FrontierJoinEstimate(
				180.0d, 170.0d, 190.0d, 0.95d,
				"frontier-v2-omni-center", FrontierFallbackReason.NONE));
		StatementPattern outer = new StatementPattern(
				Var.of("node"), Var.of("outerPredicate", outerPredicate), Var.of("value"));
		StatementPattern blocker = new StatementPattern(
				Var.of("node"), Var.of("blockerPredicate", blockerPredicate), Var.of("blocker"));
		PackedCostTestSupport.UnaryCostCall call = PackedCostTestSupport.unaryOperator(
				new Filter(outer, new Not(new Exists(blocker))));

		try (PackedCostSession session = new LmdbPackedCostModel(runtime, OptionalLong.empty(), true)
				.openSession(call.query())) {
			PackedCostEstimate outerEstimate = new PackedCostEstimate();
			session.estimateLeaf(call.inputRelationId(), call.emptyContext(), outerEstimate);
			int alternatives = 0;
			for (int relationId = 1; relationId <= call.query().relationCount(); relationId++) {
				if (!call.query().isAntiJoin(relationId)) {
					continue;
				}
				alternatives++;
				PackedCostEstimate output = new PackedCostEstimate();
				output.setContextualRows(outerEstimate.outputRows(), outerEstimate.outputRows());

				session.refineOperator(relationId,
						call.operatorContext(outerEstimate.outputRows(), outerEstimate.evidenceStateId()), output);

				assertEquals(10.0d, output.outputRows(), 1.0e-9,
						"180 joined rows over two blocker rows per key imply 90 matched outer rows");
				assertEquals(0.9d,
						output.plannedDoubleMetric("plannedSemiAntiHitProbability", Double.NaN), 1.0e-12);
				assertEquals("mapped-omni-correlated-semi-join",
						output.plannedStringMetric("plannedSemiAntiSelectivitySource"));
			}
			assertEquals(3, alternatives,
					"all physical NOT EXISTS alternatives must consume one logical Omni correlation estimate");
		}

		verify(view, times(1)).estimateJoin(any());
	}

	@Test
	void mappedV2SemiAntiPricesCompleteRhsWorkAtTheConservativeOmniBound() {
		LmdbPackedCostModel costModel = mock(LmdbPackedCostModel.class);
		var query = mock(org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.class);
		StatementPattern outer = new StatementPattern(
				Var.of("node"), Var.of("outerPredicate", VF.createIRI("urn:test:rhs-work:outer")), Var.of("value"));
		StatementPattern blocker = new StatementPattern(
				Var.of("node"), Var.of("blockerPredicate", VF.createIRI("urn:test:rhs-work:blocker")),
				Var.of("blocker"));
		Filter notExists = new Filter(outer, new Not(new Exists(blocker)));
		when(query.relationCount()).thenReturn(3);
		when(query.materializeRelation(1)).thenReturn(notExists);
		when(query.materializeRelation(2)).thenReturn(blocker);
		when(query.materializeRelation(3)).thenReturn(outer);
		when(query.isAntiJoin(1)).thenReturn(true);
		when(query.semiAntiKind(1)).thenReturn(
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_NOT_EXISTS);
		when(query.semiAntiAlgorithm(1)).thenReturn(
				org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedQueryView.SEMI_ANTI_STREAMING);
		when(query.semiAntiRightRelationId(1)).thenReturn(2);
		when(query.semiAntiCorrelationBindingCount(1)).thenReturn(1);
		when(query.semiAntiCorrelationBindingName(1, 0)).thenReturn("node");
		when(costModel.mappedRelationRows(query, 2)).thenReturn(200.0d);
		when(costModel.mappedProjectedDistinct(eq(query), any(int[].class), any(String[].class), anyDouble()))
				.thenReturn(100.0d);
		when(costModel.mappedProjectedDistinct(eq(blocker), any(String[].class), anyDouble()))
				.thenReturn(100.0d);
		when(costModel.mappedSemiAntiEstimate(eq(query), any(int[].class), eq(blocker), any(String[].class),
				anyDouble(), anyDouble(), anyDouble()))
						.thenReturn(new LmdbPackedCostModel.MappedSemiAntiEstimate(
								0.9d, 0.0d, 1.0d, 0.86d,
								"mapped-omni-correlated-semi-join", "frontier-v2-omni-center-subgraph"));
		PackedCostContext context = mock(PackedCostContext.class);
		when(context.leftInputRows()).thenReturn(100.0d);
		when(context.rightInputRows()).thenReturn(Double.NaN);
		PackedCostEstimate output = new PackedCostEstimate();
		output.setContextualRows(100.0d, 100.0d);
		output.putPlannedDoubleMetric("plannedDependentSubqueryContainsOuterIndependentWork", 1.0d);
		output.putPlannedDoubleMetric("plannedDependentSubqueryReopenObjectiveCost", 400.0d);
		output.putPlannedDoubleMetric("plannedDependentSubqueryReopenWorkRows", 400.0d);
		output.putPlannedDoubleMetric("plannedDependentSubqueryReopenResultRows", 200.0d);

		assertTrue(new LmdbMappedSemiAntiCosting(costModel, query)
				.refine(1, new int[] { 3 }, null, context, output));

		assertEquals(400.0d,
				output.plannedDoubleMetric("plannedSemiAntiStreamingExhaustionWork", Double.NaN), 0.0d);
		assertEquals(0.0d,
				output.plannedDoubleMetric("plannedSemiAntiCostingHitProbability", Double.NaN), 0.0d,
				"probe cost must use the interval endpoint that cannot underprice exhaustive misses");
		assertEquals("materialized-hash", output.plannedStringMetric("plannedSemiAntiCheapestRawAlgorithm"));
	}

